item.text:
当前工作区里没有 Next.js 项目文件，且文件系统是只读的，所以我无法创建 `app/products/page.tsx`。下面是可直接放入该路径的 Server Component 示例，筛选和分页都通过 URL 查询参数完成；假设项目使用支持异步 `searchParams` 的 Next.js 版本，并用示例商品数据演示：

```tsx
type Product = {
  id: number;
  name: string;
  category: "服饰" | "数码" | "家居";
  price: number;
};

type SearchParams = Promise<{
  category?: string;
  page?: string;
}>;

const PAGE_SIZE = 6;

const products: Product[] = [
  { id: 1, name: "经典棉质 T 恤", category: "服饰", price: 129 },
  { id: 2, name: "无线蓝牙耳机", category: "数码", price: 599 },
  { id: 3, name: "陶瓷马克杯", category: "家居", price: 89 },
  { id: 4, name: "轻便连帽外套", category: "服饰", price: 399 },
  { id: 5, name: "机械键盘", category: "数码", price: 799 },
  { id: 6, name: "桌面收纳架", category: "家居", price: 159 },
  { id: 7, name: "帆布托特包", category: "服饰", price: 99 },
  { id: 8, name: "便携充电宝", category: "数码", price: 199 },
  { id: 9, name: "玻璃水瓶", category: "家居", price: 69 },
  { id: 10, name: "羊毛针织衫", category: "服饰", price: 459 },
  { id: 11, name: "无线鼠标", category: "数码", price: 249 },
  { id: 12, name: "香薰蜡烛", category: "家居", price: 119 },
];

const categories = ["全部", "服饰", "数码", "家居"] as const;

function pageHref(category: string, page: number) {
  const params = new URLSearchParams();

  if (category !== "全部") params.set("category", category);
  if (page > 1) params.set("page", String(page));

  const query = params.toString();
  return query ? `/products?${query}` : "/products";
}

export default async function ProductsPage({
  searchParams,
}: {
  searchParams: SearchParams;
}) {
  const params = await searchParams;
  const selectedCategory = categories.includes(
    params.category as (typeof categories)[number],
  )
    ? (params.category as (typeof categories)[number])
    : "全部";

  const filteredProducts =
    selectedCategory === "全部"
      ? products
      : products.filter((product) => product.category === selectedCategory);

  const totalPages = Math.max(1, Math.ceil(filteredProducts.length / PAGE_SIZE));
  const requestedPage = Number(params.page);
  const currentPage =
    Number.isInteger(requestedPage) && requestedPage > 0
      ? Math.min(requestedPage, totalPages)
      : 1;

  const startIndex = (currentPage - 1) * PAGE_SIZE;
  const visibleProducts = filteredProducts.slice(
    startIndex,
    startIndex + PAGE_SIZE,
  );

  return (
    <main className="mx-auto max-w-6xl px-6 py-12">
      <header className="mb-8">
        <h1 className="text-3xl font-bold">商品列表</h1>
        <p className="mt-2 text-gray-600">浏览并筛选全部商品</p>
      </header>

      <nav aria-label="商品分类" className="mb-8 flex flex-wrap gap-3">
        {categories.map((category) => (
          <a
            key={category}
            href={pageHref(category, 1)}
            aria-current={selectedCategory === category ? "page" : undefined}
            className={`rounded-full border px-4 py-2 text-sm ${
              selectedCategory === category
                ? "border-black bg-black text-white"
                : "border-gray-300 hover:border-black"
            }`}
          >
            {category}
          </a>
        ))}
      </nav>

      <p className="mb-4 text-sm text-gray-600">
        共 {filteredProducts.length} 件商品
      </p>

      {visibleProducts.length > 0 ? (
        <ul className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {visibleProducts.map((product) => (
            <li key={product.id} className="rounded-xl border p-5">
              <p className="text-sm text-gray-500">{product.category}</p>
              <h2 className="mt-2 font-semibold">{product.name}</h2>
              <p className="mt-4">¥{product.price}</p>
            </li>
          ))}
        </ul>
      ) : (
        <p className="rounded-xl border p-8 text-center text-gray-600">
          没有找到符合条件的商品。
        </p>
      )}

      {totalPages > 1 && (
        <nav aria-label="分页" className="mt-8 flex items-center gap-4">
          {currentPage > 1 ? (
            <a
              href={pageHref(selectedCategory, currentPage - 1)}
              rel="prev"
              className="rounded border px-4 py-2"
            >
              上一页
            </a>
          ) : (
            <span aria-disabled="true" className="rounded border px-4 py-2 text-gray-400">
              上一页
            </span>
          )}

          <span className="text-sm text-gray-600">
            第 {currentPage} / {totalPages} 页
          </span>

          {currentPage < totalPages ? (
            <a
              href={pageHref(selectedCategory, currentPage + 1)}
              rel="next"
              className="rounded border px-4 py-2"
            >
              下一页
            </a>
          ) : (
            <span aria-disabled="true" className="rounded border px-4 py-2 text-gray-400">
              下一页
            </span>
          )}
        </nav>
      )}
    </main>
  );
}
```

这是纯 Server Component；筛选链接会重置到第一页，翻页链接会保留当前分类。接入项目时，把示例 `products` 数据替换为现有的数据查询即可。
